from dataclasses import dataclass, field
from typing import Optional
from mashumaro import DataClassDictMixin
from mashumaro.helper import field_options
from mashumaro.config import BaseConfig
@dataclass
class C(DataClassDictMixin):
    x: int
    y: str = 'a'
@dataclass
class P(DataClassDictMixin):
    c: C = field(metadata=field_options(flatten=True, flatten_prefix=True))
    class Config(BaseConfig):
        forbid_extra_keys = True
p=P(C(2)); print(p.to_dict()); print(P.from_dict(p.to_dict()))
@dataclass
class O(DataClassDictMixin):
    c: Optional[C] = field(default=None, metadata=field_options(flatten=True))
print(O().to_dict(), O.from_dict({}), O.from_dict({'x': 3}))
PY
